using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "MinimizeEffect", menuName = "Data/Battle/Effects/Enemy/Minimize Effect")]
public class MinimizeEffect : Effect
{
	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		effectOwner.GetComponent<UnitEffects>().IsEffectActiveGetEffectInstance(this).PlayBlinkingFeedback();
	}
}
